  checking: ['正在读取初始化状态', '初期化の状態を確認中', 'Checking setup status'],
  checkFailed: ['暂时无法连接后端，请确认服务已启动后重试。', 'Backend に接続できません。起動を確認して再試行してください。', 'Cannot connect to the Backend. Check that it is running and try again.'],
  connectionSettings: ['连接设置', '接続設定', 'Connection settings'],
  connectionError: ['无法读取初始化状态', '初期化の状態を取得できません', 'Cannot read setup status'],
  endpointMissing: ['后端未提供 /initialization 接口。请确认服务地址，并重启包含新版初始化接口的后端。', 'Backend に /initialization がありません。URL を確認し、新しい Backend を再起動してください。', 'Backend does not expose /initialization. Check the URL and restart the updated Backend.'],
  backend: ['后端地址', 'Backend の URL', 'Backend URL'], connect: ['连接', '接続', 'Connect'],
  localOnly: ['请在运行后端的电脑上，使用 localhost 或 127.0.0.1 打开前端完成设置。初始化不支持远程操作。', 'Backend と同じ端末で localhost または 127.0.0.1 を使って設定してください。遠隔設定はできません。', 'Complete setup on the Backend computer using localhost or 127.0.0.1. Remote setup is not supported.'],
  mailboxTestOnly: ['当前环境仅用于测试邮箱连接，暂未开放邮件向量化、模型调用或账户写入。完整初始化需使用允许这些操作的隔离测试环境。', 'この環境はメール接続のテスト専用です。メールのベクトル化、モデルの呼び出し、口座の保存は無効です。初期設定全体を試すには、これらを許可した隔離テスト環境を使用してください。', 'This environment only tests mailbox connections. Email indexing, model calls and account writes are disabled. Full setup requires an isolated test environment that allows these operations.'],
  invalidStatus: ['服务返回的初始化状态不完整，请确认后端版本后重试。', '初期化の応答が不完全です。Backend のバージョンを確認してください。', 'Setup response is incomplete. Check the Backend version and retry.'],
  keysRequired: ['请分别填写全模态 LLM 和 Embedding 服务的 API Key。', '全モーダル LLM と Embedding の両方の API キーを入力してください。', 'Enter both the all-modal LLM and embedding service API keys.'],
  queryLong: ['查询条件不能超过 2000 字符。', '検索条件は 2000 文字以内です。', 'Query must be 2,000 characters or fewer.'],
  referenceLong: ['账户标识不能超过 80 字符。', '口座識別子は 80 文字以内です。', 'Account reference must be 80 characters or fewer.'],
  accountRequired: ['请选择同币种的银行或信用账户。', '同じ通貨の銀行・クレジット口座を選んでください。', 'Select a bank or credit account in the same currency.'],
  accountInvalid: ['请检查账户名称、类型和币种。', '口座名・種類・通貨を確認してください。', 'Check the account name, type and currency.'],
  amountInvalid: ['请填写有效金额，信用额度不能为负。', '有効な金額を入力してください。限度額は負にできません。', 'Enter valid amounts. Credit limit cannot be negative.'],
  accountsFailed: ['账户列表加载失败，可点“重试”。已填写内容会保留。', '口座を取得できませんでした。「再試行」を押してください。入力内容は保持されます。', 'Could not load accounts. Choose Retry; your entries are retained.'],
  uncertain: ['提交结果暂未确认，请先点“重试”刷新状态，不要重复提交。', '送信結果を確認できません。再送信する前に「再試行」で状態を更新してください。', 'Submission outcome is unknown. Choose Retry to refresh the status before submitting again.'],
  appFailed: ['主界面加载失败，请刷新页面重试。', '画面を読み込めませんでした。再読み込みしてください。', 'Workspace could not load. Reload the page to retry.'],
